import java.util.jar.*;public final class ProfilePlatformClassLoadProof {public static void main(String[] a)throws Exception{int count=0;try(JarFile z=new JarFile(a[0])){var e=z.entries();while(e.hasMoreElements()){String n=e.nextElement().getName();if(n.endsWith(".class")){Class.forName(n.substring(0,n.length()-6).replace('/','.'),false,ProfilePlatformClassLoadProof.class.getClassLoader());count++;}}}System.out.println("LOADED_WITHOUT_INITIALIZATION="+count);}}